import type { ComponentInternalInstance } from "vue";

type Surface = () => HTMLElement | null;
export interface Layer {
  key: symbol;
  modal: boolean;
  owner: ComponentInternalInstance | null;
  surface: Surface;
  returnTo: HTMLElement | null;
}
const active: Layer[] = [];
const portals = new Set<{ owner: ComponentInternalInstance | null; surface: Surface }>();

function belongsTo(child: ComponentInternalInstance | null, parent: ComponentInternalInstance | null) {
  if (!parent) return false;
  for (let node = child; node; node = node.parent) if (node === parent) return true;
  return false;
}
function later(layer: Layer) {
  const index = active.indexOf(layer);
  return index < 0 ? [] : active.slice(index + 1);
}
export const layerManager = {
  attach(layer: Layer) {
    if (active.includes(layer)) return false;
    layer.returnTo = document.activeElement as HTMLElement | null;
    const before = active.findIndex(entry => entry.owner !== layer.owner && belongsTo(entry.owner, layer.owner));
    active.splice(before < 0 ? active.length : before, 0, layer);
    return true;
  },
  detach(layer: Layer, restore: boolean) {
    const index = active.indexOf(layer);
    if (index < 0) return;
    const wasLast = index === active.length - 1;
    const surface = layer.surface();
    for (const successor of later(layer)) {
      if (successor.returnTo && surface?.contains(successor.returnTo)) successor.returnTo = layer.returnTo;
    }
    active.splice(index, 1);
    if (restore && wasLast && layer.returnTo?.isConnected) layer.returnTo.focus({ preventScroll: true });
  },
  top(layer: Layer) { return active.at(-1) === layer; },
  modal(layer: Layer) { return active.slice().reverse().find(entry => entry.modal) === layer; },
  higher(layer: Layer, target: EventTarget | null) {
    return !!target && typeof (target as Node).nodeType === "number" && later(layer).some(entry => entry.surface()?.contains(target as Node));
  },
  scopes(layer: Layer) {
    const result = [layer.surface()];
    for (const entry of later(layer)) if (!entry.modal && belongsTo(entry.owner, layer.owner)) result.push(entry.surface());
    return result.filter((surface): surface is HTMLElement => surface !== null);
  },
  portal(owner: ComponentInternalInstance | null, surface: Surface) {
    const portal = { owner, surface };
    portals.add(portal);
    return () => portals.delete(portal);
  },
  containsPortal(owner: ComponentInternalInstance | null, target: HTMLElement) {
    for (const portal of portals) {
      const node = portal.surface();
      if (node && belongsTo(portal.owner, owner) && target.contains(node)) return true;
    }
    return false;
  },
};

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: unknown[]) {
  const combined = clsx(...inputs as ClassValue[]);
  return twMerge(combined);
}
export function clamp(value: number, min: number, max: number) {
  const aboveFloor = Math.max(min, value);
  return Math.min(aboveFloor, max);
}

@import "tailwindcss";
@import "./tokens.css";
@source "./**/*.{vue,ts}";
@source not "./**/tests/**";
@custom-variant dark (&:where(.dark, .dark *));

:root { --announcement-h: 2.5rem; }

@theme {
  --background-image-brand-bg: var(--gradient-bg);
  --background-image-brand-accent: var(--gradient-accent);
  --animate-marquee: marquee 30s linear infinite;
  --animate-marquee-vertical: marquee-vertical 30s linear infinite;
  --animate-rainbow-border: rainbow-border 3s linear infinite;
  --animate-shimmer: shimmer 2.5s linear infinite;
  --animate-action-send: action-send 520ms var(--ease-out) both;
  --animate-action-copy: action-copy 520ms var(--ease-out) both;
  --animate-action-download: action-download 540ms var(--ease-out) both;
  --animate-action-archive: action-archive 520ms var(--ease-out) both;
  --animate-action-bell: action-bell 680ms var(--ease-out) both;
  --animate-action-settings: action-settings 720ms var(--ease-out) both;
}

/* Named motion tracks are part of the public styling contract. */
@keyframes marquee { to { transform: translateX(calc(-100% - var(--gap, 1rem))); } }
@keyframes marquee-vertical { to { transform: translateY(calc(-100% - var(--gap, 1rem))); } }
@keyframes rainbow-border {
  from { background-position: 0% 50%; }
  to { background-position: 100% 50%; }
}
@keyframes shimmer {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
@keyframes action-send {
  0%, 100% { transform: translate(0, 0); }
  45% { transform: translate(2px, -2px); }
}
@keyframes action-copy {
  0%, 100% { transform: translate(0, 0); }
  40% { transform: translate(1.5px, -1.5px); }
  70% { transform: translate(-1px, 1px); }
}
@keyframes action-download {
  0%, 100% { transform: translateY(0); }
  42% { transform: translateY(2.5px); }
}
@keyframes action-archive {
  0%, 100% { transform: scale(1); }
  45% { transform: scale(0.9); }
}
@keyframes action-bell {
  0%, 100% { transform: rotate(0deg); }
  18% { transform: rotate(14deg); }
  36% { transform: rotate(-12deg); }
  54% { transform: rotate(8deg); }
  72% { transform: rotate(-5deg); }
}
@keyframes action-settings {
  from { transform: rotate(0deg); }
  to { transform: rotate(90deg); }
}

@layer base {
  html, body { overflow-x: clip; }
  html { color-scheme: light dark; }
  body {
    font-family: var(--font-sans);
    color: var(--foreground);
    background: var(--background);
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }
  a, button:not(:disabled), [role="button"]:not(:disabled) { cursor: pointer; }
  ::selection {
    color: var(--foreground);
    background: color-mix(in oklch, var(--accent) 30%, transparent);
  }
  .shiki, .shiki span { color: var(--shiki-light); }
  .dark .shiki, .dark .shiki span { color: var(--shiki-dark); }
}

@layer utilities {
  .text-balance { text-wrap: balance; }
  .text-pretty { text-wrap: pretty; }
  .scrollbar-hide { scrollbar-width: none; }
  .scrollbar-hide::-webkit-scrollbar { display: none; }
  .mask-b-fade { mask-image: linear-gradient(to bottom, black 60%, transparent); }
  .mask-radial-fade { mask-image: radial-gradient(ellipse at center, black 40%, transparent 75%); }
  .grid-noise {
    background-size: 32px 32px;
    background-image: linear-gradient(to right, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px);
  }
  .glass {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    backdrop-filter: blur(20px) saturate(160%);
    box-shadow: inset 0 1px 0 0 rgb(255 255 255 / 0.06), 0 24px 60px -24px rgb(0 0 0 / 0.45);
  }
  .glass-strong { background: var(--glass-strong-bg); backdrop-filter: blur(16px); }
  .glass-thin { background: var(--glass-thin-bg); backdrop-filter: blur(12px); border: 1px solid var(--glass-border); }
  .press { transition: transform 120ms var(--ease-out); }
  .press:active { transform: scale(0.97); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Generated from the orvui theme compatibility contract. */

:root {
  --border-strong: oklch(15% 0 0 / 0.12);
  --accent-fg: oklch(15% 0 0);
  --neon: oklch(80% 0.22 145);
  --violet: oklch(68% 0.22 295);
  --danger: oklch(62% 0.22 25);
  --success: oklch(70% 0.18 155);
  --warning: oklch(78% 0.18 75);
  --glass-bg: oklch(99% 0 0 / 0.55);
  --glass-border: oklch(15% 0 0 / 0.08);
  --glass-strong-bg: rgb(255 255 255 / 0.7);
  --glass-thin-bg: rgb(255 255 255 / 0.45);
  --gradient-bg: linear-gradient(135deg, oklch(99% 0 0) 0%, oklch(96% 0.008 210) 100%);
  --gradient-accent: linear-gradient(to right, oklch(72% 0.18 195) 0%, oklch(68% 0.22 295) 100%);
  --background: oklch(99% 0 0);
  --foreground: oklch(15% 0 0);
  --card: oklch(97% 0 0);
  --card-foreground: var(--foreground);
  --popover: var(--card);
  --popover-foreground: var(--foreground);
  --primary: #0285f7;
  --primary-foreground: #ffffff;
  --secondary: var(--card);
  --secondary-foreground: var(--foreground);
  --muted: var(--card);
  --muted-foreground: oklch(50% 0 0);
  --accent: oklch(72% 0.18 195);
  --accent-foreground: var(--accent-fg);
  --destructive: var(--danger);
  --border: oklch(15% 0 0 / 0.06);
  --input: var(--border);
  --ring: var(--border-strong);
}

.dark {
  --border-strong: rgb(255 255 255 / 0.1);
  --accent-fg: #151515;
  --neon: oklch(80% 0.22 145);
  --violet: oklch(68% 0.22 295);
  --danger: oklch(62% 0.22 25);
  --success: oklch(70% 0.18 155);
  --warning: oklch(78% 0.18 75);
  --glass-bg: rgb(28 28 28 / 0.55);
  --glass-border: rgb(255 255 255 / 0.08);
  --glass-strong-bg: rgb(28 28 28 / 0.6);
  --glass-thin-bg: rgb(21 21 21 / 0.45);
  --gradient-bg: linear-gradient(135deg, oklch(19% 0 0) 0%, oklch(22% 0.008 210) 100%);
  --gradient-accent: linear-gradient(to right, oklch(80% 0.18 195) 0%, oklch(72% 0.18 295) 100%);
  --background: #151515;
  --foreground: oklch(96% 0 0);
  --card: #1c1c1c;
  --card-foreground: var(--foreground);
